45	    setSyncing(true);
46	    try {
47	      const qs = new URLSearchParams({
48	        taskCalendarId,
49	        eblastCalendarId,
50	        ...(selectedShowId !== "all" ? { showId: selectedShowId } : {}),
51	      });
52	      const res = await fetch(`/api/export/google-calendar/sync?${qs}`, {
53	        method: "POST",
54	      });
55	      if (!res.ok) {
56	        const body = await res.json().catch(() => ({ error: res.statusText })) as { error?: string };
57	        throw new Error(body.error ?? res.statusText);
58	      }
59	      const data = await res.json() as { created: number; updated: number; deleted: number };
60	      toast({
61	        title: "Synced to Google Calendar",
62	        description: `${data.created} created, ${data.updated} updated, ${data.deleted} removed`,
63	      });
64	    } catch (err) {
65	      toast({
66	        title: "Google Calendar sync failed",
67	        description: (err as Error).message,
68	        variant: "destructive",
69	      });
70	    } finally {
71	      setSyncing(false);
72	    }
73	  };
74	
75	  const prevMonth = () => setCurrentDate(subMonths(currentDate, 1));
76	  const nextMonth = () => setCurrentDate(addMonths(currentDate, 1));
77	
78	  const handleExport = () => {
79	    const params = new URLSearchParams();
80	    if (selectedShowId !== "all") params.set("showId", selectedShowId);
81	    if (mode === "showdates") params.set("mode", "showdates");
82	    const url = `/api/export/ics${params.toString() ? `?${params}` : ""}`;
83	    const a = document.createElement("a");
84	    a.href = url;
85	    a.download = "";
86	    document.body.appendChild(a);
87	    a.click();
88	    document.body.removeChild(a);
89	  };
90	
91	  const handleToggleOfficeTask = (officeTaskId: number, currentDone: boolean) => {
92	    updateOfficeTask.mutate(
93	      { taskId: officeTaskId, data: { completed: !currentDone } },
94	      {
95	        onSuccess: () => {
96	          refetchCalendar();
97	          queryClient.invalidateQueries({ queryKey: getListOfficeTasksQueryKey() });
98	        },
99	        onError: () => toast({ title: "Failed to update task", variant: "destructive" }),
100	      }
101	    );
102	  };
103	
104	  const daysInMonth = eachDayOfInterval({
105	    start: startOfMonth(currentDate),
106	    end: endOfMonth(currentDate)
107	  });
108	
109	  // Calculate padding days for the first week
110	  const firstDayOfMonth = startOfMonth(currentDate).getDay();
111	  const paddingDays = Array.from({ length: firstDayOfMonth }).map((_, i) => i);
112	
113	  type AnyEvent = {
114	    id: number;
115	    type: string;
116	    showId?: number | null;
