156	    switch (type) {
157	      case "movein":       return "Move-In";
158	      case "eblast":       return "E-Blast";
159	      case "task":         return "Task";
160	      case "officetask":   return "Office";
161	      case "advwarehouse": return "Adv. Wh.";
