167	      default: return type;
168	    }
169	  };
170	
171	  return (
172	    <Layout>
173	      <div className="container mx-auto p-4 md:p-6 flex flex-col h-full gap-6">
174	        
175	        <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
176	          <div className="flex items-center gap-4">
177	            <h1 className="text-3xl font-bold tracking-tight">Calendar</h1>
178	            <div className="flex items-center gap-2">
179	              <Button variant="outline" size="icon" onClick={prevMonth}>
180	                <ChevronLeft className="h-4 w-4" />
181	              </Button>
182	              <div className="w-32 text-center font-semibold text-lg">
183	                {format(currentDate, "MMMM yyyy")}
184	              </div>
185	              <Button variant="outline" size="icon" onClick={nextMonth}>
186	                <ChevronRight className="h-4 w-4" />
187	              </Button>
188	            </div>
189	          </div>
190	
191	          <div className="flex items-center gap-2">
192	            <div className="flex rounded-md border overflow-hidden">
193	              <Button
194	                variant={mode === "tasks" ? "default" : "ghost"}
195	                className="rounded-none text-sm h-9 px-3"
196	                onClick={() => setMode("tasks")}
197	              >
198	                Task Dates
199	              </Button>
200	              <Button
201	                variant={mode === "showdates" ? "default" : "ghost"}
202	                className="rounded-none border-l text-sm h-9 px-3"
203	                onClick={() => setMode("showdates")}
204	              >
205	                Show Dates
206	              </Button>
207	            </div>
208	
209	            <Select value={selectedShowId} onValueChange={setSelectedShowId}>
210	              <SelectTrigger className="w-[200px]">
211	                <SelectValue placeholder="Filter by Show" />
212	              </SelectTrigger>
213	              <SelectContent>
214	                <SelectItem value="all">All Shows</SelectItem>
